workflowDoc.first_request_example:
import requests
import json

url = "{{origin}}/api/v2/workflow/invoke"

payload = json.dumps({
   "workflow_id": "{{workflowId}}",
   "stream": False, # イベントをストリーミングで返すかどうか（既定値：True）。この例では応答全体を確認するため False を指定しています。対話型アプリではストリーミングを推奨します。
})

headers = {
   'Content-Type': 'application/json'
}

response = requests.request("POST", url, headers=headers, data=payload)

print(response.text)# ワークフローの応答を出力

