workflowDoc.event_schema_example:
{
  "event": "guide_word",  
  # イベントの種類。例：guide_word（開始メッセージ）、guide_question（質問候補）、input（入力待ち）、output_msg（出力）、close（終了）。

  "node_id": "input_xxxx",  
  # イベントを発生させたノード。入力イベント（event="input" など）の場合、次のリクエストに node_id を含めて入力先を指定します。 

  "message_id": "xxxxxxx",  
  # データベース内の一意のメッセージ ID

  "node_execution_id": "xxxxx",  
  # ノード実行の一意の ID。同じノードが複数回実行される場合、実行やストリーミングメッセージの区別に使用します。

  "input_schema": {   # input_schema：空でなければ、対応する入力 UI を表示します。
    "input_type": "form_input",  
    # input_type：1) form_input：フォーム、2) dialogue_input：チャット欄、3) message_inline_input：メッセージ内入力、4) 選択肢メッセージ。

    "value": [  # ユーザーの入力項目。input_type により異なります。
      {
        "key": "category",  # ユーザー入力の組み立てに使う一意のフィールドキー
        "type": "select",  # フィールドの種類：text（テキスト欄）、file（アップロード）、select（ドロップダウン）
        "value": "",  # フィールドの既定値
        "multiple": True,  # type=select の場合、複数選択を許可するかどうか
        "label": "次の操作を選択してください",  # 画面に表示するフィールド名
        "options": [  # type=select の場合、各選択肢の id や text などを指定します。
          {
            "id": "0b8a2fe9",
            "text": "操作 1",
            "type": ""
          },
          {
            "id": "eb5f4ade",
            "text": "操作 2",
            "type": ""
          }
        ],  
        "required": True  # 入力が必須かどうか
      }
    ]
  },
  "output_schema": {# 会話画面に表示するデータ
    "message": "出力内容",  # ユーザーに直接表示するテキスト出力。
    "reasoning_content"："思考内容" # R1 などの推論モデルの思考内容
    "output_key": "output",  # 出力に対応する変数の識別子
    "files": [  # 各ファイルの path と name を含む一覧。ダウンロードやプレビューの表示に使用します。
      {
        "path": "http://minio:9000/xxx.png?aa=xxx",
        "name": "テスト画像.png"
      }
    ],
    "extra": "{"qa": "この回答の出典は既存の QA ナレッジベースです", "url": null}"  # QA ナレッジベースの出典情報
  },
}

